) AS v(order_code, product_id, user_id, rating, content, customer_name, size, color, created_at)
JOIN orders o ON o.order_code = v.order_code
JOIN order_items oi ON oi.order_id = o.id AND oi.product_id = v.product_id;

UPDATE order_items SET reviewed = TRUE WHERE id IN (SELECT order_item_id FROM product_reviews) AND order_id IN (SELECT id FROM orders WHERE order_code LIKE 'SYN-%');

-- 7. product aggregates (same formulas as V20260929000000__datafix_indexes_and_backfill.sql)
UPDATE products p SET total_reviews = COALESCE(agg.cnt, 0), average_rating = COALESCE(agg.avg_rating, 0.0)
FROM products p2 LEFT JOIN (
  SELECT product_id, COUNT(*) AS cnt, AVG(rating)::double precision AS avg_rating
  FROM product_reviews WHERE status = 'APPROVED' GROUP BY product_id
) agg ON agg.product_id = p2.id
WHERE p.id = p2.id;
UPDATE products p SET sold_count = COALESCE(agg.total_qty, 0)
FROM products p2 LEFT JOIN (
  SELECT oi.product_id, SUM(oi.quantity) AS total_qty FROM order_items oi
  JOIN orders o ON o.id = oi.order_id WHERE o.status = 'DELIVERED' GROUP BY oi.product_id
) agg ON agg.product_id = p2.id
WHERE p.id = p2.id;

COMMIT;
